import collections

def run_simulation_with_order_tracking(plant_period, cap_config, target_product, target_day):
    products_node = node_by_title(doc, f"{plant_period}: Products")
    ledger_node = node_by_title(doc, f"{plant_period}: Daily ledger")

    products_info = {}
    for row_idx, row in table_rows(products_node):
        products_info[row['product']] = {
            'kg_per_unit': float(row['kg per unit']),
            'opening_stock': int(row['opening stock'])
        }

    ledger_data = collections.defaultdict(list)
    for row_idx, row in table_rows(ledger_node):
        day = int(row['day'])
        ledger_data[day].append({
            'product': row['product'],
            'produced': int(row['produced']),
            'ordered': int(row['ordered'])
        })

    product_list = sorted(products_info.keys())
    stock = {p: products_info[p]['opening_stock'] for p in product_list}
    order_queue = []
    order_id_counter = 0

    target_order_id = None
    target_order_shipped_full_on_day = None

    for day in range(71, 85):
        capacity = cap_config.get(day, cap_config.get('default', 300000))

        for entry in ledger_data[day]:
            p = entry['product']
            stock[p] += entry['produced']

        day_orders = []
        for entry in ledger_data[day]:
            p = entry['product']
            qty = entry['ordered']
            if qty > 0:
                day_orders.append((qty, p))

        day_orders.sort()
        for qty, p in day_orders:
            oid = order_id_counter
            order_queue.append({'product': p, 'rem': qty, 'day': day, 'id': oid})
            if p == target_product and day == target_day:
                target_order_id = oid
            order_id_counter += 1

        for order in order_queue:
            p = order['product']
            kg_per_unit = products_info[p]['kg_per_unit']
            if order['rem'] > 0:
                can_ship_stock = stock[p]
                can_ship_cap = int(capacity // kg_per_unit)
                ship_qty = min(order['rem'], can_ship_stock, can_ship_cap)
                if ship_qty > 0:
                    stock[p] -= ship_qty
                    capacity -= ship_qty * kg_per_unit
                    order['rem'] -= ship_qty

        # Check if target order shipped in full today
        if target_order_id is not None:
            for order in order_queue:
                if order['id'] == target_order_id and order['rem'] == 0:
                    target_order_shipped_full_on_day = day
                    break

        order_queue = [o for o in order_queue if o['rem'] > 0]

    return target_order_shipped_full_on_day

cap_scenario = {'default': 300000}
for d in range(75, 85):
    cap_scenario[d] = 240000

shipped_day = run_simulation_with_order_tracking("Plant 2114, Period 06", cap_scenario, "SOS500M24P", 81)
print(f"Order for SOS500M24P placed on day 81 shipped in full on day: {shipped_day}")

